module gcd_table_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] data_in,\n    input data_valid,\n    output reg [7:0] result,\n    output reg result_valid,\n    output reg done\n);\n    \n    // State definitions\n    localparam [3:0] S_IDLE             = 4'd0;\n    localparam [3:0] S_INPUT            = 4'd1;\n    localparam [3:0] S_SORT             = 4'd2;\n    localparam [3:0] S_BUILD_DISTINCT   = 4'd3;\n    localparam [3:0] S_FIND_CANDIDATE   = 4'd4;\n    localparam [3:0] S_DECREMENT_CANDIDATE = 4'd5;\n    localparam [3:0] S_PROCESS_RESULTS  = 4'd6;\n    localparam [3:0] S_COMPUTE_GCD      = 4'd7;\n    localparam [3:0] S_FIND_GCD         = 4'd8;\n    localparam [3:0] S_DECREMENT_GCD    = 4'd9;\n    localparam [3:0] S_APPEND_RESULT    = 4'd10;\n    localparam [3:0] S_OUTPUT           = 4'd11;\n    localparam [3:0] S_DONE             = 4'd12;\n    \n    reg [3:0] state, next_state;\n    reg [7:0] buffer [0:15];\n    reg [7:0] distinct [0:15];\n    reg [7:0] counts [0:15];\n    reg [3:0] distinct_count;\n    reg [7:0] results [0:3];\n    reg [3:0] results_count;\n    reg [7:0] current_candidate;\n    \n    reg [7:0] sort_i, sort_j;\n    reg [3:0] input_counter;\n    reg [3:0] distinct_idx;\n    reg [3:0] candidate_idx;\n    reg swapped;\n    reg [2:0] gcd_count;\n    reg [7:0] gcd_value;\n    reg [3:0] output_counter;\n    reg [2:0] result_idx;\n    reg [3:0] gcd_current_idx;\n    \n    reg [7:0] a_temp, b_temp;\n    reg [7:0] curr_gcd_target;\n    reg [4:0] timeout_counter;\n    \n    // Iterative GCD function\n    function automatic [7:0] gcd(input [7:0] a, b);\n        reg [7:0] temp;\n        begin\n            gcd = a;\n            temp = b;\n            while (temp != 8'd0) begin\n                {gcd, temp} = {temp, gcd % temp};\n            end\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result_valid <= 1'b0;\n            result <= 8'd0;\n            input_counter <= 4'd0;\n            output_counter <= 4'd0;\n            results_count <= 4'd0;\n            distinct_count <= 4'd0;\n            timeout_counter <= 5'd0;\n            \n            for (sort_i = 0; sort_i < 16; sort_i = sort_i + 8'd1) begin\n                buffer[sort_i] <= 8'd0;\n                distinct[sort_i] <= 8'd0;\n                counts[sort_i] <= 8'd0;\n                if (sort_i < 4) results[sort_i] <= 8'd0;\n            end\n        end else begin\n            timeout_counter <= timeout_counter + 5'd1;\n            \n            // Timeout handling\n            if (timeout_counter == 5'd31) begin\n                state <= S_DONE;\n                done <= 1'b1;\n            end\n            \n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    result_valid <= 1'b0;\n                    timeout_counter <= 5'd0;\n                    if (start) begin\n                        state <= S_INPUT;\n                        input_counter <= 4'd0;\n                    end\n                end\n                \n                S_INPUT: begin\n                    if (data_valid) begin\n                        buffer[input_counter] <= data_in;\n                        input_counter <= input_counter + 4'd1;\n                        if (input_counter == 4'd15) begin\n                            state <= S_SORT;\n                            sort_i <= 8'd0;\n                            swapped <= 1'b0;\n                        end\n                    end\n                end\n                \n                S_SORT: begin\n                    for (sort_j = 0; sort_j < 15 - sort_i; sort_j = sort_j + 8'd1) begin\n                        if (buffer[sort_j] < buffer[sort_j+1]) begin\n                            // Swap values\n                            buffer[sort_j] <= buffer[sort_j+1];\n                            buffer[sort_j+1] <= buffer[sort_j];\n                            swapped <= 1'b1;\n                        end\n                    end\n                    sort_i <= sort_i + 8'd1;\n                    if (sort_i >= 15 || !swapped) begin\n                        state <= S_BUILD_DISTINCT;\n                        distinct_idx <= 4'd0;\n                        distinct_count <= 4'd0;\n                    end\n                end\n                \n                S_BUILD_DISTINCT: begin\n                    if (buffer[distinct_idx] != distinct[distinct_count]) begin\n                        distinct[distinct_count] <= buffer[distinct_idx];\n                        counts[distinct_count] <= 8'd1;\n                        distinct_count <= distinct_count + 4'd1;\n                    end else begin\n                        counts[distinct_count-1] <= counts[distinct_count-1] + 8'd1;\n                    end\n                    distinct_idx <= distinct_idx + 4'd1;\n                    if (distinct_idx == 4'd15) state <= S_FIND_CANDIDATE;\n                end\n                \n                S_FIND_CANDIDATE: begin\n                    current_candidate <= 8'd0;\n                    candidate_idx <= 4'd0;\n                    for (candidate_idx = 0; candidate_idx < distinct_count; candidate_idx = candidate_idx + 4'd1) begin\n                        if (counts[candidate_idx] > 0 && distinct[candidate_idx] > current_candidate) begin\n                            current_candidate <= distinct[candidate_idx];\n                        end\n                    end\n                    state <= S_DECREMENT_CANDIDATE;\n                end\n                \n                S_DECREMENT_CANDIDATE: begin\n                    for (candidate_idx = 0; candidate_idx < distinct_count; candidate_idx = candidate_idx + 4'd1) begin\n                        if (distinct[candidate_idx] == current_candidate) begin\n                            counts[candidate_idx] <= counts[candidate_idx] - 8'd1;\n                        end\n                    end\n                    state <= S_PROCESS_RESULTS;\n                    gcd_current_idx <= 4'd0;\n                end\n                \n                S_PROCESS_RESULTS: begin\n                    if (gcd_current_idx < results_count) begin\n                        a_temp <= current_candidate;\n                        b_temp <= results[gcd_current_idx];\n                        state <= S_COMPUTE_GCD;\n                    end else begin\n                        state <= S_APPEND_RESULT;\n                    end\n                end\n                \n                S_COMPUTE_GCD: begin\n                    gcd_value <= gcd(a_temp, b_temp);\n                    state <= S_FIND_GCD;\n                    gcd_count <= 3'd0;\n                end\n                \n                S_FIND_GCD: begin\n                    if (gcd_count < distinct_count) begin\n                        if (distinct[gcd_count] == gcd_value) begin\n                            counts[gcd_count] <= counts[gcd_count] - 8'd2;\n                            gcd_current_idx <= gcd_current_idx + 4'd1;\n                            state <= S_PROCESS_RESULTS;\n                        end\n                        gcd_count <= gcd_count + 3'd1;\n                    end else begin\n                        gcd_current_idx <= gcd_current_idx + 4'd1;\n                        state <= S_PROCESS_RESULTS;\n                    end\n                end\n                \n                S_APPEND_RESULT: begin\n                    results[results_count] <= current_candidate;\n                    results_count <= results_count + 4'd1;\n                    if (results_count == 4'd3) state <= S_OUTPUT;\n                    else state <= S_FIND_CANDIDATE;\n                end\n                \n                S_OUTPUT: begin\n                    if (output_counter < 4'd4) begin\n                        result <= results[output_counter];\n                        result_valid <= 1'b1;\n                        output_counter <= output_counter + 4'd1;\n                    end else begin\n                        result_valid <= 1'b0;\n                        state <= S_DONE;\n                    end\n                end\n                \n                S_DONE: begin\n                    done <= 1'b1;\n                    if (!start) state <= S_IDLE;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule